import React, { useEffect, useRef, useState } from 'react';
import { ChevronLeft, ChevronRight } from '@hexa-ui/icons';
import { onKeyEnter } from '../../utils/utils';
import Styled from './MobilePagination.styles';
import { Paragraph } from '../../../typography';

interface Props {
  currentPage: number;
  total: number;
  handlePageChange: (page: number) => void;
  disabled: boolean | undefined;
  pageSize: number;
}

const MobilePagination = ({
  currentPage,
  total,
  handlePageChange,
  disabled,
  pageSize,
}: Props): JSX.Element => {
  const [inputVisible, setInputVisible] = useState(false);
  const [inputValue, setInputValue] = useState(currentPage.toString());
  const inputRef = useRef<HTMLInputElement>(null);
  const numberOfPages = Math.ceil(total / pageSize);

  useEffect(() => {
    if (inputVisible) {
      inputRef?.current?.focus();
      inputRef?.current?.select();
    }
  }, [inputVisible]);

  const onPageIndicatorClick = () => {
    if (disabled) return;
    setInputVisible(true);
  };

  const handlePressEnter = (event: React.KeyboardEvent<HTMLDivElement>) => {
    const isEnter = event.key === 'Enter';
    if (isEnter && !disabled) {
      setInputVisible(true);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const onlyNumbers = /^[0-9]*$/;
    const { value } = e.target;

    if (onlyNumbers.test(value)) {
      setInputValue(value);
    }
  };

  const handleInputBlur = () => {
    if (Number(inputValue) > numberOfPages) {
      handlePageChange(numberOfPages);
      setInputValue(numberOfPages.toString());
    } else if (Number(inputValue) === 0) {
      setInputValue('1');
      handlePageChange(1);
    } else {
      handlePageChange(Number(inputValue));
    }
    setInputVisible(false);
  };

  const handleNavigatorClick = (pageNumber: number) => {
    if (inputVisible) setInputVisible(false);
    handlePageChange(pageNumber);
  };

  return (
    <Styled.Container>
      <Styled.NavigatorContainer
        onClick={() => handleNavigatorClick(currentPage - 1)}
        onKeyDown={(e: React.KeyboardEvent<HTMLLIElement>) =>
          onKeyEnter(e, () => handlePageChange(currentPage - 1))
        }
        isDoubleLeft
        bordered
        disabled={disabled || currentPage === 1}
        tabIndex={disabled || currentPage === 1 ? -1 : 0}
        title="previous page"
      >
        <Styled.Anchor
          aria-label="go to previous page"
          rel="nofollow"
          aria-disabled={disabled || currentPage === 1 ? true : undefined}
        >
          <ChevronLeft size="medium" />
        </Styled.Anchor>
      </Styled.NavigatorContainer>
      <Styled.ListItem>
        {inputVisible ? (
          <Styled.Input
            onChange={handleInputChange}
            onBlur={handleInputBlur}
            inputMode="numeric"
            value={inputValue}
            ref={inputRef}
            aria-labelledby="page number"
          />
        ) : (
          <Styled.PageIndicatorContainer
            tabIndex={disabled ? -1 : 0}
            disabled={disabled}
            onKeyDown={handlePressEnter}
          >
            <Paragraph
              size="small"
              alignment="center"
              weight="semibold"
              colortype={disabled ? 'disabled' : 'primary'}
              onClick={onPageIndicatorClick}
            >{`${currentPage} of ${numberOfPages}`}</Paragraph>
          </Styled.PageIndicatorContainer>
        )}
      </Styled.ListItem>
      <Styled.NavigatorContainer
        onClick={() => handleNavigatorClick(currentPage + 1)}
        onKeyDown={(e: React.KeyboardEvent<HTMLLIElement>) =>
          onKeyEnter(e, () => handlePageChange(currentPage + 1))
        }
        disabled={disabled || currentPage === numberOfPages}
        isDoubleRight
        bordered
        tabIndex={disabled || currentPage === numberOfPages ? -1 : 0}
        title="next page"
      >
        <Styled.Anchor
          aria-label="go to next page"
          rel="nofollow"
          aria-disabled={disabled || currentPage === numberOfPages ? true : undefined}
        >
          <ChevronRight size="medium" />
        </Styled.Anchor>
      </Styled.NavigatorContainer>
    </Styled.Container>
  );
};

export default MobilePagination;
